{
  "items": [
    {
      "title": "ARD/ZDF Medienstudie – Media Usage in Germany (2024–2026)",
      "url_or_doi": "https://www.ard-zdf-medienstudie.de/reports",
      "justification": "One of the most comprehensive sources on media consumption in Germany. Provides survey results on television, radio, newspapers, streaming services, social media, podcasts, and internet usage. Includes demographic breakdowns by age and gender. The study began in 2024, continuing earlier ARD/ZDF research. Particularly useful for examining the transformation of Germany's media landscape in the 2020s. Published results are accessible, although restrictions apply to data reuse."
    },
    {
      "title": "ARD/ZDF Onlinestudie and Massenkommunikation Trends (2010–2023)",
      "url_or_doi": "https://www.ard-zdf-medienstudie.de/",
      "justification": "Historical survey series documenting German internet adoption and media consumption throughout the 2010s and early 2020s. Covers online news, video streaming, social media, digital communication, and traditional media consumption. The annual Onlinestudie provides particularly valuable longitudinal information. Its historical results complement the newer ARD/ZDF Medienstudie."
    },
    {
      "title": "GESIS Eurobarometer – Media Use Trends (2010–2025)",
      "url_or_doi": "https://www.gesis.org/en/eurobarometer-data-service/overview/eb-trends-trend-files/list-of-trends/media-use",
      "justification": "Provides longitudinal survey data on media consumption across European countries, including Germany. Covers television viewing, radio listening, newspaper reading, internet usage, and online social networking. Includes surveys from 2010 through 2025, making it particularly suitable for analyzing changes between the 2010s and 2020s. German respondents can be selected for country-specific analysis, and the data support international comparisons."
    },
    {
      "title": "GESIS Eurobarometer – Primary Survey Datasets",
      "url_or_doi": "https://www.gesis.org/en/eurobarometer-data-service/data-and-documentation",
      "justification": "Provides access to original Eurobarometer survey datasets, questionnaires, codebooks, and documentation. Researchers can extract German observations and analyze media consumption, media trust, information sources, and attitudes toward digital communication. Particularly useful for academic research requiring individual-level survey data and statistical analysis across multiple years."
    },
    {
      "title": "Reuters Institute Digital News Report – Germany 2025",
      "url_or_doi": "https://reutersinstitute.politics.ox.ac.uk/digital-news-report/2025/germany",
      "justification": "Country-specific survey findings on news consumption in Germany. Covers digital news platforms, traditional journalism, social media, public broadcasting, trust in news, and changing audience behavior. Particularly useful for studying digital transformation, journalism, and news consumption in Germany during the 2020s."
    },
    {
      "title": "Reuters Institute Digital News Report – Germany 2015",
      "url_or_doi": "https://reutersinstitute.politics.ox.ac.uk/our-research/digital-news-report-2015-0",
      "justification": "Historical international survey examining digital news consumption in 2015, including Germany. Provides information on online news audiences, digital platforms, changing consumption habits, and news industry developments. Valuable as a reference point for comparing the German digital news environment of the mid-2010s with developments in the 2020s."
    },
    {
      "title": "Reuters Institute Digital News Report – Country and Market Data 2025",
      "url_or_doi": "https://reutersinstitute.politics.ox.ac.uk/digital-news-report/2025/country-and-market-data?page=3",
      "justification": "Provides comparative country-level indicators from the Digital News Report survey, including Germany. Useful for examining audience behavior, news consumption, and changes in digital journalism across national media markets. Supports comparisons between Germany and other countries using standardized survey measures."
    },
    {
      "title": "Reuters Institute Digital News Report 2024 – Data and Resources",
      "url_or_doi": "https://reutersinstitute.politics.ox.ac.uk/digital-news-report/2024/resources",
      "justification": "Provides access to research resources, charts, and published data from the 2024 Digital News Report. Includes Germany among the surveyed markets. Relevant for studying online news consumption, news trust, social media as a news source, and digital journalism. Particularly useful for comparative research on media consumption during the 2020s."
    },
    {
      "title": "ARD/ZDF Massenkommunikation – Longitudinal Media Usage Study (1964–2020)",
      "url_or_doi": "https://www.ard-zdf-medienstudie.de/",
      "justification": "A long-running German media consumption study with survey waves covering 2010, 2015, and 2020. Examines television, radio, newspapers, internet usage, and the time people spend consuming different media. Particularly valuable for analyzing structural changes in media consumption during the 2010s and comparing them with 2020. Historical publications and results are available through the ARD/ZDF study archive."
    },
    {
      "title": "Media Perspektiven – Historical Television and Video Statistics",
      "url_or_doi": "https://www.media-perspektiven.de/basisdaten/video/basisdaten-archiv-video/bewegtbild",
      "justification": "Provides historical statistical tables covering German television and video consumption. Includes television viewing figures, audience shares, streaming service usage, and audiovisual media consumption during the late 2010s and 2020s. Particularly useful for analyzing the transition from traditional television broadcasting to online streaming platforms."
    },
    {
      "title": "Media Perspektiven – German Media Companies and Ownership Structures",
      "url_or_doi": "https://www.media-perspektiven.de/basisdaten/medienkonzerne-und-beteiligungen",
      "justification": "Contains information and visualizations documenting ownership structures and corporate relationships among major German media companies. Draws on information maintained by Germany's Commission on Concentration in the Media (KEK). Useful for researching media ownership, corporate concentration, and the structure of Germany's broadcasting and publishing industries, particularly in the 2020s."
    },
    {
      "title": "Euromedia Ownership Monitor – European Media Ownership Database",
      "url_or_doi": "https://media-ownership.eu/",
      "justification": "Searchable database of European media ownership, including German media organizations. Provides information on owners, companies, and ownership networks, with machine-readable data available. Particularly useful for studying ownership concentration, cross-media corporate relationships, and transparency in Germany's contemporary media market."
    },
    {
      "title": "Media Ownership Monitor Germany",
      "url_or_doi": "https://germany.mom-gmr.org/",
      "justification": "Country-specific database documenting media ownership and concentration in Germany. Relevant for identifying influential media organizations, their owners, and relationships between companies operating in television, radio, print, and digital journalism. Particularly useful for research on media pluralism, ownership transparency, and concentration in the German media market."
    },
    {
      "title": "German Federal Statistical Office – Media Industry Business Statistics",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/48121/table/48121-0003",
      "justification": "Official German economic statistics covering enterprises, employment, revenue, and business characteristics across industries, including broadcasting and related media sectors. Provides a quantitative foundation for examining the economic development of Germany's media industry. Useful for analyzing market structure and changes in the broadcasting industry across available years."
    },
    {
      "title": "German Federal Statistical Office – Publishing Industry Enterprise Statistics",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/47415/table/47415-0033",
      "justification": "Official statistical dataset containing information on German businesses categorized by economic activity, including newspaper, magazine, and other publishing activities. Relevant for studying the structure and economic development of the German publishing sector. Particularly useful for examining changes in traditional print media businesses and comparing publishing activities with other industries."
    },
    {
      "title": "German Federal Statistical Office – Book Production Statistics",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/21611/table/21611-0210",
      "justification": "Official statistical table documenting book title production in Germany by year and subject category. Useful for studying trends in German publishing, cultural production, and the print media sector. Provides a complementary perspective on media development beyond television, digital news, and social media."
    },
    {
      "title": "German Federal Statistical Office – Digital Purchases of Media Products",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/122%2A/table/12231-0002",
      "justification": "Official household survey statistics concerning online purchases in Germany, including books, newspapers, magazines, films, and music in physical or digital formats. Includes demographic dimensions such as age. Useful for investigating changes in consumer behavior and the digitalization of media markets during the 2020s."
    },
    {
      "title": "German Federal Statistical Office – Retail Price Index for Newspapers and Magazines",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/61%2A/table/61131-0001",
      "justification": "Official time-series data on retail price developments in Germany, including newspaper and magazine retail activities. Useful for studying economic pressures affecting traditional print media and changes in the cost environment for newspaper and magazine distribution during the 2010s and 2020s."
    },
    {
      "title": "GESIS Flash Eurobarometer – Civic Engagement and Media Habits (2020)",
      "url_or_doi": "https://search.gesis.org/research_data/ZA7772?lang=en",
      "justification": "Survey dataset collected in February 2020 across European countries, including Germany. Contains information on civic engagement and media habits. Researchers can analyze German respondents separately and investigate relationships between media behavior and civic participation. Particularly useful for research connecting information consumption, communication, and political engagement at the beginning of the 2020s."
    },
    {
      "title": "ARD/ZDF Medienstudie – Research Dataset in B2FIND",
      "url_or_doi": "https://b2find.eudat.eu/dataset/bd28b4b7-1e41-5dfd-90c8-537107b5bbde",
      "justification": "Research data catalogue record for the ARD/ZDF Medienstudie, published through the GESIS Data Archive infrastructure. Documents research on media consumption in Germany beginning in 2024. Useful for discovering academic dataset metadata and identifying archival information associated with representative German media usage surveys. Data access conditions should be checked separately."
    }
  ]
}
